True def transform(grid):
    h, w = len(grid), len(grid[0])
    out = []
    for y in range(3 * h):
        if y < h:
            sy = h - 1 - y
        elif y < 2 * h:
            sy = y - h
        else:
            sy = 3 * h - 1 - y
        out.append([grid[sy][w - 1 - x] for x in range(w)] + list(grid[sy]))
    return out
